path.style:
fill: var(--prism-module-fill, rgba(18, 25, 32, 0.96));
                 stroke: var(--prism-module-stroke, #76D8C0);
                 stroke-width: 1.2;

fill: none;
                 stroke: var(--prism-module-accent, #76D8C0);
                 stroke-width: 0.65;
                 opacity: 0.38;

fill: none;
                 stroke: var(--prism-module-accent, #76D8C0);
                 stroke-width: 0.75;
                 opacity: 0.46;

text.style:
font-family: Inter, Segoe UI, Arial, sans-serif;
                 text-anchor: start;
                 font-weight: 700;
                 font-size: 6px;
                 letter-spacing: 0;
                 fill: var(--prism-module-glyph, rgba(232, 238, 244, 0.84));

font-family: Inter, Segoe UI, Arial, sans-serif;
                 text-anchor: middle;
                 font-size: 5.5px;
                 font-style: normal;
                 fill: var(--text-muted, rgba(176, 190, 204, 0.66));
